{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C18"],
      "claim": "Trazodone, a very high-transfer analogue with a piperazine/aryl-heterocycle core, has absolute oral bioavailability of 82% in young men and 63–91% across human studies, directly supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C51"],
      "claim": "Ketanserin, the closest structural analogue sharing the 4-fluorobenzoyl-piperidine and fused heterocycle motif, has absolute oral bioavailability of 45 ± 7% in hypertensive patients, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C45"],
      "claim": "Sertindole, a piperidine antipsychotic with a fluorophenyl group, has oral bioavailability of 75% in patients, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C44"],
      "claim": "Cerivastatin, a fluorophenyl-containing drug, has absolute oral bioavailability of 60% in humans, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C61"],
      "claim": "Pirazolac, a fluorophenyl carboxylic acid, is completely systemically available (F ≈ 1) in young healthy volunteers, supporting high bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Maraviroc, a piperidine-containing drug with lower but still above-threshold absolute bioavailability of 23% at 100 mg, supports high at the F ≥ 20% threshold.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "All high-transfer human absolute bioavailability data for close analogues (trazodone, ketanserin, sertindole, cerivastatin, pirazolac, maraviroc) are ≥20%, with most values ≥50%; therefore the query is predicted to have high oral bioavailability at the F≥20% threshold.",
  "evidence_gaps": [
    "No direct human absolute bioavailability measurement exists for the query molecule itself.",
    "The query's benzimidazolone/butyrophenone connectivity is not identical to any single analogue, so extrapolation relies on high transfer scores and shared pharmacophore features."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

